import{_ as e,o,a,b as i}from"./app.DKoEZOcr.js";const r="/ascendc.github.io/pr/5487/assets/code_optimization.BSTCL0A0.png",u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD算子性能优化","link":"/guide/operator_practice/simd_operator_optimization/simd_operator_optimization"},{"text":"矢量计算","link":"/guide/operator_practice/simd_operator_optimization/vector_compute/vector_compute"},{"text":"基于全局掩码复用的计算性能优化","link":"/guide/operator_practice/simd_operator_optimization/vector_compute/mask_reuse_optimization"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_optimization/vector_compute/mask_reuse_optimization.md","filePath":"guide/operator_practice/simd_operator_optimization/vector_compute/mask_reuse_optimization.md","lastUpdated":1786954352000}'),s={name:"guide/operator_practice/simd_operator_optimization/vector_compute/mask_reuse_optimization.md"};function p(n,t,c,_,d,l){return o(),a("div",null,[...t[0]||(t[0]=[i('<div><article class="markdown-body"><h1>基于全局掩码复用的计算性能优化</h1><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明 该性能优化建议适用于如下产品型号：</p><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li></ul></div></div><p>【优先级】高</p><p>【描述】当<strong>连续执行多个</strong>向量计算操作（如多次Adds、Muls等）且这些操作共享<strong>相同的掩码配置参数</strong>（如掩码长度、掩码值和掩码模式一致）时，存在性能优化空间。此时，若每次调用计算接口时都启用内部掩码设置（即<strong>isSetMask=true</strong>），将被迫重复执行一整套掩码初始化流程：包括设置掩码模式SetMaskCount、设置掩码值（SetVectorMask）、重置掩码（ResetMask）以及重置掩码模式（SetMaskNorm）。这一系列操作在硬件层面需要耗费大量cycle，尤其在高频计算中，会拖慢整体执行效率。在计算规模较小时，由于实际计算耗时短，而掩码配置的固定开销占总耗时比例较高，优化策略能显著降低相对开销，实现高比例性能提升。</p><p>【优化方案】</p><p>在这些场景中，掩码配置保持不变的情况下，遵循“<strong>一次性全局配置，后续复用</strong>”的核心原则：在所有连续计算操作执行之前，通过调用<strong>SetVectorMask</strong>接口完成<strong>全局掩码</strong>的一次性、完整设置mask；随后，所有后续的向量计算接口调用均应将<strong>isSetMask</strong>参数设置为<strong>false</strong>，以明确指示接口跳过内部掩码设置流程，直接<strong>复用已预置</strong>的全局掩码状态。</p><p><strong>图1</strong> 代码优化<br><img src="'+r+'" alt><a id="图1-代码优化"></a></p><p>理论分析：SetMaskCount、SetMask、ResetMask、SetMaskNorm四个接口，每个接口调用耗时1cycle，连续调用180次Adds计算接口，共节省4×180 = 720cycles。</p></article></div>',1)])])}const g=e(s,[["render",p]]);export{u as __pageData,g as default};
